void Solver::bump_var(int var, double coeff) {
    double inc = var_inc * coeff;
    activity[var] += inc;

    const double ACTIVITY_LIMIT = 1e300;   // very high to avoid frequent rescales
    if (activity[var] > ACTIVITY_LIMIT) {
        const double SCALE = 1e-300;
        for (int i = 1; i <= vars; ++i) activity[i] *= SCALE;
        var_inc *= SCALE;
    }

    if (vsids.inHeap(var)) vsids.update(var);
}
